import json
from pathlib import Path
HOLD={'dev-20261022-001','dev-20261022-002','dev-20261022-003','dev-20261026-002'}
# channel promotion w/m may also be hold - check if in list
files=sorted(Path('/tmp/sess_full').glob('*.json'))
print('files', len(files))
for p in files:
  code=p.stem
  try:
    d=json.loads(p.read_text())
  except Exception as e:
    print(code, 'BAD', e); continue
  # unwrap
  stj=d.get('state_json') or {}
  if isinstance(stj,str):
    stj=json.loads(stj)
  # index fields sometimes top-level
  title=d.get('title') or stj.get('title') or ''
  ss=d.get('stage_status') or stj.get('stage_status') or {}
  def done(k):
    return ss.get(str(k))=='done'
  undone=[i for i in range(1,7) if not done(i)]
  prs=d.get('publish_request_status')
  arch=d.get('is_archived')
  reviewer=d.get('publish_reviewer_username') or d.get('publish_reviewer_display_name')
  note=(d.get('publish_request_note') or '')[:80]
  runs=stj.get('publish_runs') or d.get('publish_runs') or []
  owned=stj.get('dolphin_owned_tasks') or []
  test_owned=[o for o in owned if isinstance(o,dict) and o.get('env')=='test']
  s4=stj.get('stage4_spark') or {}
  mount=s4.get('mount') if isinstance(s4,dict) else {}
  if not isinstance(mount,dict): mount={}
  s4d=stj.get('stage4_dolphin_check') or {}
  s5=stj.get('stage5_prod_dryrun') or {}
  s6=stj.get('stage6_commit') or {}
  outs=stj.get('outputs') or []
  target=stj.get('target') or {}
  # check outputs layers
  out_ok=all(o.get('layer') and o.get('table_name') for o in outs) if outs else False
  # stage4 checks for spark
  etl=s4.get('etlRan') or s4.get('etl_ran')
  created=s4.get('created')
  pb=s4.get('playbookConfirmed') or s4.get('playbook_confirmed')
  # also nested under stage4_db_check
  s4db=stj.get('stage4_db_check') or {}

  blockers=[]
  if undone: blockers.append(f'undone={undone}')
  if arch: blockers.append('archived')
  if prs=='pending': blockers.append('pending')
  if prs=='approved': blockers.append('approved')
  if len(runs)>0: blockers.append(f'runs={len(runs)}')
  if not outs: blockers.append('no_outputs')
  elif not out_ok: blockers.append('outputs_incomplete')
  mount_ok=bool(mount.get('ok'))
  if not mount_ok and not test_owned:
    blockers.append('no_mount/owned')
  elif not mount_ok and test_owned:
    blockers.append('dolphin_owned_only_no_spark_mount')
  if code in HOLD: blockers.append('HOLD_#11251_snap')
  # s5/s6 presence
  if not s5: blockers.append('no_s5')
  if not s6 or not (s6.get('sha') or s6.get('pushed')):
    blockers.append('no_s6_commit')

  ready = (not undone and not arch and prs not in ('pending','approved') 
